"""Shared data and terminal primitives for the independently implemented viewer."""
import os
import re
import sys
import pathlib
import zipfile

ESC = '\x1b['
RESET = ESC + '0m'

def resource(name):
    base = os.path.dirname(__file__)
    try:
        return pathlib.Path(base, 'resources', name).read_text()
    except (OSError, NotADirectoryError):
        with zipfile.ZipFile(base) as archive:
            return archive.read('resources/' + name).decode()

def output(s, err=False):
    stream = sys.stderr.buffer if err else sys.stdout.buffer
    stream.write(s if isinstance(s, bytes) else s.encode('utf-8', 'replace'))

def warning(s, err=True):
    output(ESC + '33m[bat warning]' + RESET + ': ' + s + '\n', err)

def error(s):
    output(ESC + '31m[bat error]' + RESET + ': ' + s + '\n', True)

class AppError(Exception):
    pass

class CliError(Exception):
    pass

def paths():
    home = os.path.expanduser('~')
    config = os.path.join(os.environ.get('XDG_CONFIG_HOME') or os.path.join(home, '.config'), 'bat')
    cache = os.environ.get('BAT_CACHE_PATH') or os.path.join(os.environ.get('XDG_CACHE_HOME') or os.path.join(home, '.cache'), 'bat')
    return config, cache, os.environ.get('BAT_CONFIG_PATH') or os.path.join(config, 'config')

ANSI = re.compile(r'\x1b(?:\[[0-?]*[ -/]*[@-~]|\][^\x07\x1b]*(?:\x07|\x1b\\)|[()][0-2A-Z]|[@-Z\\-_])')

def charwidth(c):
    import unicodedata
    if c == '\t':
        return 1
    if ord(c) < 32 or 0x7f <= ord(c) < 0xa0:
        return 0
    if unicodedata.combining(c) or unicodedata.category(c) in ('Mn', 'Me', 'Cf'):
        return 0
    return 2 if unicodedata.east_asian_width(c) in ('W','F') else 1

def textwidth(s):
    return sum(charwidth(c) for c in ANSI.sub('', s))

def lines_bytes(data):
    # str.splitlines also treats many non-newline control bytes as line endings.
    parts = data.split(b'\n')
    return [p+b'\n' for p in parts[:-1]] + ([parts[-1]] if parts[-1] else [])

def lines_text(data):
    parts = data.split('\n')
    return [p+'\n' for p in parts[:-1]] + ([parts[-1]] if parts[-1] else [])
PY
