"""Parsing and evaluating inclusive line selections."""
import re
from common import AppError

MAX = (1 << 64) - 1

def integer(s):
    if not s:
        raise AppError('cannot parse integer from empty string')
    if not re.fullmatch(r'\+?[0-9]+', s):
        raise AppError('invalid digit found in string')
    n = int(s)
    if n > MAX:
        raise AppError('number too large to fit in target type')
    return n

class Range:
    def __init__(self, text):
        self.tail = False
        p = text.split(':')
        if len(p) > 3:
            raise AppError("Line range contained too many ':' characters. Expected format: 'N', 'N:M', 'N::C', or 'N:M:C'")
        if len(p) == 1:
            self.a = self.b = integer(p[0]); return
        if len(p) == 3:
            if not p[0] or not p[2]:
                raise AppError('invalid digit found in string')
            a = integer(p[0])
            b = integer(p[1]) if p[1] else a
            try:
                c = integer(p[2])
            except AppError:
                raise AppError('Invalid context number in N:M:C format' if p[1] else 'Invalid context number in N::C format')
            self.a, self.b = max(0, a-c), min(MAX, b+c)
            return
        a, b = p
        if a.startswith('-') and b == '':
            self.tail = True
            self.a, self.b = integer(a[1:]), MAX
        elif a == '' and b.startswith('-'):
            self.tail = True
            self.a, self.b = MAX, integer(b[1:])
        elif not b:
            self.a, self.b = integer(a), MAX
        elif not a:
            self.a, self.b = 1, integer(b)
        else:
            self.a = integer(a)
            if b.startswith('+'):
                self.b = min(MAX,self.a + integer(b[1:]))
            elif b.startswith('-'):
                self.b = self.a
                self.a = max(1,self.a - integer(b[1:]))
            else:
                self.b = integer(b)

    def bounds(self, count):
        if self.tail:
            if self.a == MAX:
                return (1, max(0,count-self.b))
            return (max(1,count-self.a+1), count)
        return self.a, self.b

    def contains(self, n, count):
        a,b = self.bounds(count)
        return a <= n <= b

def contains(ranges, n, count):
    return not ranges or any(r.contains(n,count) for r in ranges)
