        wrap=self.get('wrap','auto')
        if self.has('chop-long-lines'): wrap='never'
        self.wrap = ('character' if self.tty or ws else 'never') if wrap=='auto' else wrap
        self.advanced=self.color or bool(self.style)
        self.tabs=int(self.get('tabs',4 if self.style or self.tty else 0))
        if self.has('show-all') and self.tabs==0: self.tabs=4
        self.squeeze=int(self.get('squeeze-limit','1')) if self.has('squeeze-blank') else None
        self.italic=self.get('italic-text','never')=='always'
        self.truecolor=os.environ.get('COLORTERM','') in ('truecolor','24bit')
        self.theme=self.get('theme','auto')
        if self.theme in ('auto','auto:always','auto:system','dark'):
            self.theme=self.get('theme-dark','Monokai Extended')
        elif self.theme=='light': self.theme=self.get('theme-light','Monokai Extended Light')
