"""User-defined syntax and theme assets in a compact, local cache format."""
import os
import json
import re
import plistlib
from pathlib import Path
from common import paths, AppError, output

CUSTOM_SYNTAXES={}
CUSTOM_THEMES={}
BLANK_THEMES=False

def unquote(s):
    s=s.strip()
    if len(s)>=2 and s[0]==s[-1] and s[0] in '\'"':
        if s[0]=="'":return s[1:-1].replace("''", "'")
        try:return json.loads(s)
        except Exception:return s[1:-1]
    return s.split(' #',1)[0].rstrip()

def read_syntax(path):
    text=path.read_text(encoding='utf-8')
    name=re.search(r'^name:\s*(.+)$',text,re.M)
    name=unquote(name[1]) if name else path.stem
    extension=re.search(r'^file_extensions:\s*\[([^\]]*)\]',text,re.M)
    extensions=[unquote(x) for x in extension[1].split(',') if x.strip()] if extension else []
    if not extension:
        m=re.search(r'^file_extensions:\s*\n((?:\s+-[^\n]*\n?)+)',text,re.M)
        if m:extensions=[unquote(x) for x in re.findall(r'^\s+-\s*(.*)$',m[1],re.M)]
    rules=[]
    rule=None
    for line in text.splitlines():
        m=re.match(r'\s+-\s+match:\s*(.*)',line)
        if m:
            if rule:rules.append(rule)
            rule={'pattern':unquote(m[1]),'scope':'text.plain'}
        elif rule:
            m=re.match(r'\s+scope:\s*(.+)',line)
            if m:rule['scope']=unquote(m[1])
    if rule:rules.append(rule)
    return {'name':name,'extensions':extensions,'rules':rules}

def build(source,target,blank=False,ack=False):
    target=Path(target);source=Path(source)
    themes={};syntaxes={}
    if (source/'themes').is_dir():
        for path in sorted((source/'themes').rglob('*.tmTheme')):
            try:
                with path.open('rb') as f:theme=plistlib.load(f)
                themes[path.stem]=theme
            except Exception as e:raise AppError("Could not load theme '"+str(path)+"': "+str(e))
    if (source/'syntaxes').is_dir():
        for path in sorted((source/'syntaxes').rglob('*.sublime-syntax')):
            definition=read_syntax(path);syntaxes[definition['name']]=definition
    if not themes:output(f"No themes were found in '{source}/themes', using the default set\n")
    if not syntaxes:output(f"No syntaxes were found in '{source}/syntaxes', using the default set.\n")
    target.mkdir(parents=True,exist_ok=True)
    for desc,name,data in [('theme set','themes.bin',{'themes':themes,'blank':blank and bool(themes)}),('syntax set','syntaxes.bin',{'syntaxes':syntaxes,'blank':blank and bool(syntaxes)})]:
        with (target/name).open('w') as f:json.dump({'viewer_format':1,**data},f)
        output(f'Writing {desc} to {target}/{name} ... okay\n')
    (target/'metadata.yaml').write_text('version: 0.26.1\n')
    output(f'Writing metadata to folder {target} ... okay\n')

def load(opts):
    global BLANK_THEMES
    if opts.has('no-custom-assets'):return
    _,cache,_=paths()
    for filename,kind in [('themes.bin','themes'),('syntaxes.bin','syntaxes')]:
        try:
            with open(os.path.join(cache,filename)) as f:data=json.load(f)
        except (OSError,UnicodeError,ValueError):continue
        if data.get('viewer_format')!=1:continue
        if kind=='themes':
            CUSTOM_THEMES.update(data.get(kind,{}));BLANK_THEMES=data.get('blank',False)
        else:
            CUSTOM_SYNTAXES.update(data.get(kind,{}))
            from syntax import LANGUAGES
            if data.get('blank'):LANGUAGES[:]=[['Plain Text','txt']]
            for name,syntax in CUSTOM_SYNTAXES.items():
                LANGUAGES[:]=[l for l in LANGUAGES if l[0]!=name]
                LANGUAGES.append([name,','.join(syntax['extensions'])])
            LANGUAGES.sort(key=lambda x:x[0].casefold())

def lex_custom(language,text):
    definition=CUSTOM_SYNTAXES[language];compiled=[]
    for rule in definition.get('rules',[]):
        try:compiled.append((re.compile(rule['pattern']),rule['scope']))
        except re.error:continue
    result=[];pos=0
    while pos<len(text):
        candidates=[]
        for ix,(regex,scope) in enumerate(compiled):
            match=regex.search(text,pos)
            if match and match.end()>match.start():candidates.append((match.start(),ix,match,scope))
        if not candidates:
            result.append((text[pos:],'plain'));break
        _,_,m,scope=min(candidates,key=lambda x:(x[0],x[1]))
        if m.start()>pos:result.append((text[pos:m.start()],'plain'))
        result.append((m[0],'custom.'+scope));pos=m.end()
    return result

def rgb_code(hexstr,truecolor):
    s=hexstr.lstrip('#')
    if len(s)==3:s=''.join(c*2 for c in s)
    try:r,g,b=(int(s[i:i+2],16) for i in (0,2,4))
    except Exception:r,g,b=255,255,255
    if truecolor:return f'38;2;{r};{g};{b}'
    cube=[0,95,135,175,215,255]
    rgb=[(rr,gg,bb) for rr in cube for gg in cube for bb in cube]+[(8+i*10,)*3 for i in range(24)]
    index=min(range(len(rgb)),key=lambda i:sum((a-v)**2 for a,v in zip(rgb[i],(r,g,b))))
    return '38;5;'+str(index+16)

def role_scope(role):
    if role.startswith('custom.'):return role[7:]
    end=role.split('.',1)[-1]
    if end.startswith('comment') or end.startswith('docstring'):return 'comment'
    if end.startswith(('keyword','operator')):return 'keyword'
    if end.startswith('string'):return 'string.quoted'
    if end in ('number','constant','null','escape'):return 'constant.numeric'
    if end in ('function','call'):return 'entity.name.function'
    if end in ('type','builtin'):return 'support.function'
    if end=='class':return 'entity.name.class'
    if end.startswith('punct'):return 'punctuation'
    if end=='param':return 'variable.parameter'
    return 'text.plain'

def theme_style(theme,role,opts):
    scope=role_scope(role);settings={}
    entries=theme.get('settings',[])
    for item in entries:
        if not item.get('scope'):settings.update(item.get('settings',{}))
    for item in entries:
        selectors=item.get('scope','').split(',')
        if any(selector.strip() and (scope==selector.strip() or scope.startswith(selector.strip()+'.')) for selector in selectors):
            settings.update(item.get('settings',{}))
    style=[];font=settings.get('fontStyle','')
    if 'bold' in font:style.append('1')
    if 'italic' in font and opts.italic:style.append('3')
    if 'underline' in font:style.append('4')
    style.append(rgb_code(settings.get('foreground','#FFFFFF'),opts.truecolor))
    return ';'.join(style)
